import { describe, it, expect } from "vitest";
import { createArcRotateCamera } from "@babylonjs/lite";
import type { SceneContext } from "@babylonjs/lite";
import { attachLimitedOrbit } from "./limited-orbit";

function fakeCanvas() {
    const map = new Map<string, Set<Function>>();
    return {
        map,
        setPointerCapture() {},
        releasePointerCapture() {},
        addEventListener(ev: string, h: Function) {
            if (!map.has(ev)) map.set(ev, new Set());
            map.get(ev)!.add(h);
        },
        removeEventListener(ev: string, h: Function) {
            map.get(ev)?.delete(h);
        },
        fire(ev: string, e: any) {
            for (const h of [...(map.get(ev) ?? [])]) h(e);
        },
        count() {
            let n = 0;
            for (const s of map.values()) n += s.size;
            return n;
        },
    };
}
const touch = (id: number, x: number, y: number) => ({ identifier: id, clientX: x, clientY: y });
const frame = (scene: any) => { for (const f of [...scene._beforeRender]) f(); };

describe("attachLimitedOrbit", () => {
    it("clamps start, wheel, pinch, and cleans up", () => {
        const cam = createArcRotateCamera(0, 1, 50, { x: 0, y: 0, z: 0 } as any);
        const scene: any = { _beforeRender: [] };
        const canvas = fakeCanvas();
        const dispose = attachLimitedOrbit(cam, canvas as any, scene as SceneContext, 2, 10);
        expect(cam.radius).toBe(10);
        const seen: number[] = [];
        for (let i = 0; i < 200; i++) {
            canvas.fire("wheel", { deltaY: i % 2 ? 5000 : -5000, preventDefault() {} });
            frame(scene);
            seen.push(cam.radius);
        }
        expect(Math.min(...seen)).toBeGreaterThanOrEqual(2);
        expect(Math.max(...seen)).toBeLessThanOrEqual(10);
