        for (const d of [1000, 1, 5000, 0.5, 300, 2, 20000]) {
            canvas.fire("touchmove", { preventDefault() {}, changedTouches: [touch(2, d, 0)] });
            expect(cam.radius).toBeGreaterThanOrEqual(2);
            expect(cam.radius).toBeLessThanOrEqual(10);
            frame(scene);
            expect(cam.radius).toBeGreaterThanOrEqual(2);
            expect(cam.radius).toBeLessThanOrEqual(10);
        }
        dispose();
        dispose();
        expect(canvas.count()).toBe(0);
        expect(scene._beforeRender.length).toBe(0);
        expect(cam._clampToLimits).toBeUndefined();
        expect(cam.lowerRadiusLimit).toBeUndefined();
        cam.radius = 100;
        expect(cam.radius).toBe(100);
    });
    it("rejects bad ranges", () => {
        const cam = createArcRotateCamera(0, 1, 5, { x: 0, y: 0, z: 0 } as any);
        expect(() => attachLimitedOrbit(cam, fakeCanvas() as any, { _beforeRender: [] } as any, 10, 2)).toThrow(RangeError);
        expect(() => attachLimitedOrbit(cam, fakeCanvas() as any, { _beforeRender: [] } as any, NaN, 2)).toThrow(RangeError);
    });
});
